import{_ as e,o as n,c as p,am as s}from"./chunks/framework._FJXuPhs.js";const g=JSON.parse('{"title":"SpringCloud_组件基本使用_Gateway","description":"","frontmatter":{"title":"SpringCloud_组件基本使用_Gateway","excerpt":"SpringCloud_组件基本使用_Gateway","date":"2023-12-04 09:59:05","updated":"2023-12-04 09:59:05"},"headers":[],"relativePath":"框架/微服务&分布式/框架 SpringCloud/SpringCloud_组件基本使用_Gateway.md","filePath":"框架/微服务&分布式/框架 SpringCloud/SpringCloud_组件基本使用_Gateway.md","lastUpdated":null}'),l={name:"框架/微服务&分布式/框架 SpringCloud/SpringCloud_组件基本使用_Gateway.md"};function t(o,a,i,r,c,d){return n(),p("div",null,[...a[0]||(a[0]=[s(`<h3 id="_1、微服务网关是什么" tabindex="-1">1、微服务网关是什么 <a class="header-anchor" href="#_1、微服务网关是什么" aria-label="Permalink to &quot;1、微服务网关是什么&quot;">​</a></h3><p>微服务网关是一个位于微服务架构前端的服务，作为客户端和后端微服务之间的中介。它的作用是集中处理和管理微服务系统的一些共享的非业务功能，提供统一的入口，同时可以进行路由、转发、过滤、监控等操作。</p><blockquote><p>Gateway 的基本功能</p></blockquote><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202312041349886.png" alt="image.png"></p><ol><li><strong>路由转发：</strong><ul><li>网关负责接收客户端的请求，根据配置的路由规则将请求转发到不同的微服务。这有助于实现前后端的解耦，使得微服务可以独立演进。</li></ul></li><li><strong>流量控制：</strong><ul><li>网关可以对请求进行流量控制，限制每个微服务的访问频率，防止某个微服务被过度请求而影响整体系统的稳定性。</li></ul></li><li><strong>熔断保护：</strong><ul><li>网关可以实现熔断保护，当某个微服务出现故障或超时时，网关可以快速拦截请求，避免请求堆积导致整个系统的崩溃。Sentinel是一种专注于流量控制、熔断降级、系统自适应保护的开源框架，它提供了更丰富的熔断保护功能，因此有些项目选择引入Sentinel来增强熔断保护能力。</li></ul></li><li><strong>日志监控：</strong><ul><li>网关通常会记录请求和响应的日志信息，这有助于进行系统的监控和故障排查。业务日志和链路追踪也是重要的监控手段。</li></ul></li><li><strong>安全认证：</strong><ul><li>网关可以提供安全认证机制，确保只有经过认证和授权的用户才能访问微服务。这可以通过集成框架（如Spring Security）或使用专门的认证服务来实现。</li></ul></li></ol><blockquote><p>关于 Gateway 的熔断保护功能的说明</p></blockquote><p>Spring Cloud Gateway自身具备基本的熔断保护机制，可以在配置中设置断路器的一些参数，但相对简单。对于一些更复杂的熔断、限流、降级等场景，可能需要引入专门的框架如Sentinel。</p><p>在实际使用中，可以根据具体的需求来选择是否引入Sentinel。如果项目对熔断保护等功能的需求相对简单，Gateway的基本熔断保护足够使用。如果需要更复杂的流量控制和熔断降级策略，引入Sentinel可能会更为合适。</p><blockquote><p>服务网关和流量网关的区别</p></blockquote><p>对于 Nginx 和 Gateway 的两者区别：</p><p>流量网关（如Nignx)提供全局性的、与后端业务应用无关的策略，例如 HTTPS证书卸载、Web防火墙、全局流量监控等。</p><p>微服务网关（如Spring Cloud Gateway）是指与业务紧耦合的、提供单个业务域级别的策略，如服务治理、身份认证等。</p><p>流量网关负责南北向流量调度及安全防护，微服务网关负责东西向流量调度及服务治理。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202312041354467.png" alt="image.png|400"></p><h4 id="版本区分" tabindex="-1">版本区分 <a class="header-anchor" href="#版本区分" aria-label="Permalink to &quot;版本区分&quot;">​</a></h4><ul><li><strong>2.0.x 版本</strong>：引入了基于WebFlux的反应式编程模型，不再使用传统的Servlet API。提供了基本的路由、过滤功能。</li><li><strong>2.1.x 版本</strong>：增加了对WebSocket的支持，改进了路由断言和过滤器的功能。</li><li><strong>2.2.x 版本</strong>：引入了更多的路由断言和过滤器，增强了安全性和可管理性。</li><li><strong>3.0.x 版本</strong>：更新了底层的Spring Boot和Spring Framework的版本，支持最新的功能，例如更好的错误处理和性能优化。</li></ul><p>一般说我们常见的是2.2 版本就行</p><h3 id="_2、gateway-的搭建和使用" tabindex="-1">2、Gateway 的搭建和使用 <a class="header-anchor" href="#_2、gateway-的搭建和使用" aria-label="Permalink to &quot;2、Gateway 的搭建和使用&quot;">​</a></h3><blockquote><p>网关的搭建</p></blockquote><p>略</p><blockquote><p>Spring Cloud Gateway 的配置项</p></blockquote><p>Spring Cloud Gateway的核心概念包括路由（Route）、断言（Predicate）和过滤器（Filter）。</p><p>这些概念共同构成了Gateway的基础，用于定义请求的路由规则、请求的匹配条件和请求的处理流程。</p><blockquote><p>路由</p></blockquote><p>路由定义了请求应该被定向到哪个目标服务。每个路由都包含一个唯一的ID、目标URI、一组断言和过滤器。通过配置多个路由，可以实现对请求的动态路由和负载均衡。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>spring:</span></span>
<span class="line"><span>  cloud:</span></span>
<span class="line"><span>    gateway:</span></span>
<span class="line"><span>      routes:</span></span>
<span class="line"><span>        - id: example</span></span>
<span class="line"><span>          uri: http://example.com</span></span>
<span class="line"><span>          predicates:</span></span>
<span class="line"><span>            - Path=/example/**</span></span>
<span class="line"><span>          filters:</span></span>
<span class="line"><span>            - StripPrefix=1</span></span></code></pre></div><p>上述配置表示将以<code>/example/**</code>路径开头的请求转发到<code>http://example.com</code>，并在转发时去掉路径的第一个段（StripPrefix=1）。</p><blockquote><p>断言</p></blockquote><p>断言定义了请求匹配的条件，当条件满足时，对应的路由规则生效。断言可以基于请求的路径、方法、头部信息等进行匹配。</p><blockquote><p>过滤器</p></blockquote><p>过滤器是处理请求和响应的逻辑的组件，它们可以修改请求和响应，实现一些额外的功能，如添加头信息、修改请求体、进行认证等</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>spring:</span></span>
<span class="line"><span>  cloud:</span></span>
<span class="line"><span>    gateway:</span></span>
<span class="line"><span>      routes:</span></span>
<span class="line"><span>        - id: example</span></span>
<span class="line"><span>          uri: http://example.com</span></span>
<span class="line"><span>          predicates:</span></span>
<span class="line"><span>            - Path=/example/**</span></span>
<span class="line"><span>          filters:</span></span>
<span class="line"><span>            - StripPrefix=1</span></span>
<span class="line"><span>            - AddRequestHeader=X-Header=foo</span></span></code></pre></div><p>上述配置中的过滤器<code>AddRequestHeader=X-Header=foo</code>表示在转发请求前，向请求头中添加一个名为<code>X-Header</code>的头，其值为<code>foo</code>。</p><blockquote><p>Gateway集成 nacos 注册中心实现服务发现</p></blockquote><p>略</p><blockquote><p>Gateway 整合 Apollo 实现动态路由配置</p></blockquote><p>略</p><blockquote><p>自定义全局异常处理器</p></blockquote><p>to be contined....</p><hr><p>参考</p><ul><li><a href="https://blog.csdn.net/yao583224426/article/details/122216804" target="_blank" rel="noreferrer">https://blog.csdn.net/yao583224426/article/details/122216804</a></li><li><a href="https://cloud.tencent.com/developer/article/2135737" target="_blank" rel="noreferrer">https://cloud.tencent.com/developer/article/2135737</a></li><li><a href="https://spring.io/projects/spring-cloud-gateway" target="_blank" rel="noreferrer">https://spring.io/projects/spring-cloud-gateway</a></li></ul>`,42)])])}const h=e(l,[["render",t]]);export{g as __pageData,h as default};
